using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "FreezeEnemyEffect", menuName = "Data/Battle/Effects/Freeze Enemy Effect")]
public class FreezeEnemyEffect : Effect
{
	[Header("Freeze Color")]
	[SerializeField]
	private Color freezeColor = Color.blue;

	[SerializeField]
	private float freezeColorTransitionDuration;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effectOwner.GetComponent<CorruptedAnimalSpriteControl>();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		int num = effectAmount - 1;
		if (num == 0)
		{
			RemoveEffect(num, effectOwner);
		}
		return num;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<CorruptedAnimalSpriteControl>();
	}
}
